-- Дело 9704 v2: реакции на «свои» и очевидные улики (без сброса партий)
begin;
update characters set reaction_rules = coalesce(reaction_rules,'[]'::jsonb) || '[{"id": "R83", "on": "4f67be3f-f5f7-5ab5-bb69-611053df3042", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Даник говорил, что переписал номера. Я ещё рассердилась: зачем, лишь бы Игоря отпустили.\n(пауза)\nА он, выходит, правильно сделал. Один из нас.", "grants": []}, {"id": "R84", "on": "552b22f9-f4c6-5469-8d1c-56bde54906aa", "requires": ["b170d031-ba6c-5e70-829f-cbd96f761931"], "text": "— Оттуда, значит, звонили. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"4f67be3f-f5f7-5ab5-bb69-611053df3042": "— Даник говорил, что переписал номера. Я ещё рассердилась: зачем, лишь бы Игоря отпустили.\n(пауза)\nА он, выходит, правильно сделал. Один из нас.", "552b22f9-f4c6-5469-8d1c-56bde54906aa": "— Оттуда, значит, звонили. Из пустого дома.\n(закрывает глаза)\nА я сидела у аппарата и ждала. Думала, он где-то далеко. А он был в городе. Под землёй."}'::jsonb where id = '0e8eb7cc-a947-5525-80eb-0978454d919b' and not (reaction_rules @> '[{"id": "R83"}]'::jsonb);  -- Валентина Петровна Сартакова
update characters set reaction_rules = coalesce(reaction_rules,'[]'::jsonb) || '[{"id": "R71", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "Фархад одёргивает рукав пальто, прячет руку.\n— Ерунда. Поранился. По хозяйству.\n(кашляет в кулак)\nЗаживёт. Вы не за этим пришли, товарищ следователь.", "grants": []}, {"id": "R72", "on": "4cc34317-760f-577c-b05f-e0374aee4f23", "requires": [], "text": "— Ну, был на базе. В октябре. К Игорю зашёл, по старой памяти.\n(пожимает плечами)\nПоговорили и разошлись. Что тут записывать? Охрана у них от скуки всех пишет.", "grants": []}, {"id": "R73", "on": "00b31a8e-e1ee-5474-a323-177b43b153d3", "requires": [], "text": "— Обыск, значит, сделали. Ну, мои ботинки. Зимние. Сорок третий.\n(долго смотрит на каблук)\nПорез? Где-то зацепил. Мало ли где человек ходит, товарищ следователь.", "grants": []}, {"id": "R74", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Это мои сбережения. Всю жизнь копил.\nВ банк сейчас только дурак понесёт: сегодня банк есть, завтра нет.\n(отворачивается)\nА бумаги Шмидтов у меня по доверенности. Дом продаю, люди попросили.", "grants": []}, {"id": "R75", "on": "b322dfba-0cb0-52bc-9610-328a905bc004", "requires": [], "text": "— Долги отдавал. Людям.\nЯ в девяносто третьем всё потерял на этих фондах, как и полгорода. Занимал, теперь отдаю.\nЭто что, запрещено?", "grants": []}, {"id": "R76", "on": "6a92b637-cb0c-5bf4-8495-f503839bf08c", "requires": [], "text": "— Олжас? Племянник. Сестры сын.\nИз аула приехал, учится. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём.", "grants": []}, {"id": "R77", "on": "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c", "requires": [], "text": "— Валя-апа переживает, ей всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)", "grants": []}, {"id": "R87", "on": "e34a96b0-5d0e-5414-9ef3-048071ef84ed", "requires": [], "text": "Фархад долго молчит. Кашляет.\n— Игорь... Двадцать лет его знал. Мальчишкой ко мне пришёл.\n(отворачивается)\nНе надо мне это показывать, товарищ следователь.", "grants": []}, {"id": "R88", "on": "c2c5ba62-e24e-523f-93bc-d8909b28e717", "requires": [], "text": "— Подвал как подвал. Я дом продаю, по доверенности.\nВ подвал не лазил, что мне там делать.\n(кашляет)\nПокупателям кухню показывал, комнаты.", "grants": []}, {"id": "R89", "on": "87af9a91-8540-5177-bdd6-3e156802fc75", "requires": [], "text": "— Шарф...\n(не смотрит)\nМало ли у кого какие шарфы. Не знаю.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"abc6fac8-abbd-5589-b6b5-958cd368e7fe": "Фархад одёргивает рукав пальто, прячет руку.\n— Ерунда. Поранился. По хозяйству.\n(кашляет в кулак)\nЗаживёт. Вы не за этим пришли, товарищ следователь.", "4cc34317-760f-577c-b05f-e0374aee4f23": "— Ну, был на базе. В октябре. К Игорю зашёл, по старой памяти.\n(пожимает плечами)\nПоговорили и разошлись. Что тут записывать? Охрана у них от скуки всех пишет.", "00b31a8e-e1ee-5474-a323-177b43b153d3": "— Обыск, значит, сделали. Ну, мои ботинки. Зимние. Сорок третий.\n(долго смотрит на каблук)\nПорез? Где-то зацепил. Мало ли где человек ходит, товарищ следователь.", "2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Это мои сбережения. Всю жизнь копил.\nВ банк сейчас только дурак понесёт: сегодня банк есть, завтра нет.\n(отворачивается)\nА бумаги Шмидтов у меня по доверенности. Дом продаю, люди попросили.", "b322dfba-0cb0-52bc-9610-328a905bc004": "— Долги отдавал. Людям.\nЯ в девяносто третьем всё потерял на этих фондах, как и полгорода. Занимал, теперь отдаю.\nЭто что, запрещено?", "6a92b637-cb0c-5bf4-8495-f503839bf08c": "— Олжас? Племянник. Сестры сын.\nИз аула приехал, учится. Я ему помогаю, как могу. Мальчик хороший.\n(резко)\nЕго не трогайте. Он тут ни при чём.", "e4f03eb4-b50d-54c1-9edd-8e3fc38dad1c": "— Валя-апа переживает, ей всякое кажется.\nСобака это. На базаре, у мясных рядов. Я же ей говорил.\n(прячет руку)", "e34a96b0-5d0e-5414-9ef3-048071ef84ed": "Фархад долго молчит. Кашляет.\n— Игорь... Двадцать лет его знал. Мальчишкой ко мне пришёл.\n(отворачивается)\nНе надо мне это показывать, товарищ следователь.", "c2c5ba62-e24e-523f-93bc-d8909b28e717": "— Подвал как подвал. Я дом продаю, по доверенности.\nВ подвал не лазил, что мне там делать.\n(кашляет)\nПокупателям кухню показывал, комнаты.", "87af9a91-8540-5177-bdd6-3e156802fc75": "— Шарф...\n(не смотрит)\nМало ли у кого какие шарфы. Не знаю."}'::jsonb where id = '5b4c1ece-ba00-50d6-9113-73e03e05ccd8' and not (reaction_rules @> '[{"id": "R71"}]'::jsonb);  -- Фархад Мамаджанов
update characters set reaction_rules = coalesce(reaction_rules,'[]'::jsonb) || '[{"id": "R78", "on": "0a295d5f-e115-5c89-a26a-5992761304a0", "requires": [], "text": "— Виктор, значит.\n(снимает очки)\nБыл разговор. По деньгам. Партнёры иногда ругаются.\nК тому, что с Игорем случилось, это отношения не имеет.", "grants": []}, {"id": "R79", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Значит, проверили. Хорошо.\n(выдыхает)\nЯ вам с самого начала говорил: я его не трогал. Деньги — да. Но не это.", "grants": []}, {"id": "R80", "on": "06da149b-c92c-54fa-a5f5-b78ff87dbc92", "requires": [], "text": "— Вот видите. Сходится.\n(поправляет ручку на столе)\nЯ виноват перед Игорем. Но не в этом.", "grants": []}, {"id": "R85", "on": "5cdb3307-fe10-53c5-a365-6998256b7d7a", "requires": [], "text": "— Фархад принёс. В воскресенье вечером, я там был.\nВалентина Петровна плакала, а он её по руке гладил.\n(пожимает плечами)\nПятьсот долларов у человека, который всем должен. Я тогда ещё подумал: откуда.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"0a295d5f-e115-5c89-a26a-5992761304a0": "— Виктор, значит.\n(снимает очки)\nБыл разговор. По деньгам. Партнёры иногда ругаются.\nК тому, что с Игорем случилось, это отношения не имеет.", "9281d556-d163-5537-a0e2-e4cd2e635ba5": "— Значит, проверили. Хорошо.\n(выдыхает)\nЯ вам с самого начала говорил: я его не трогал. Деньги — да. Но не это.", "06da149b-c92c-54fa-a5f5-b78ff87dbc92": "— Вот видите. Сходится.\n(поправляет ручку на столе)\nЯ виноват перед Игорем. Но не в этом.", "5cdb3307-fe10-53c5-a365-6998256b7d7a": "— Фархад принёс. В воскресенье вечером, я там был.\nВалентина Петровна плакала, а он её по руке гладил.\n(пожимает плечами)\nПятьсот долларов у человека, который всем должен. Я тогда ещё подумал: откуда."}'::jsonb where id = 'a7955352-673d-5ff7-bfcc-506079544d1f' and not (reaction_rules @> '[{"id": "R78"}]'::jsonb);  -- Данияр Ахметов
update characters set reaction_rules = coalesce(reaction_rules,'[]'::jsonb) || '[{"id": "R86", "on": "2d1a03f4-be7f-5007-8fe1-71c12d498c29", "requires": [], "text": "— Доверенность? Да, Отто ему оставил, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну, ja. Это уж я не знаю.", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"2d1a03f4-be7f-5007-8fe1-71c12d498c29": "— Доверенность? Да, Отто ему оставил, когда уезжали. Дом продавать.\nКлючи тоже у него. Он и покупателей водил.\n(качает головой)\nА доллары... Ну, ja. Это уж я не знаю."}'::jsonb where id = '631694f6-0ec1-523d-9f2a-599f875223c1' and not (reaction_rules @> '[{"id": "R86"}]'::jsonb);  -- Тамара Фёдоровна Шнайдер
update characters set reaction_rules = coalesce(reaction_rules,'[]'::jsonb) || '[{"id": "R81", "on": "46e78eb0-d057-5e5d-8a00-81457f8f3d20", "requires": [], "text": "— Моё это. Куртка, шапка, ботинки.\nДеньги? Заработал. На базаре грузил, ночами.\n(смотрит в сторону)\nЧто, нельзя?", "grants": []}, {"id": "R82", "on": "9281d556-d163-5537-a0e2-e4cd2e635ba5", "requires": [], "text": "— Я же сказал уже. Был там. Держал его.\n(смотрит в пол)\nА дальше я не знаю. Меня там не было.", "grants": []}, {"id": "R90", "on": "abc6fac8-abbd-5589-b6b5-958cd368e7fe", "requires": [], "text": "— Аке руку поранил? Не знаю.\nЯ его давно не видел. Учёба, работа.\n(трёт ладони о колени)", "grants": []}]'::jsonb, reactions = coalesce(reactions,'{}'::jsonb) || '{"46e78eb0-d057-5e5d-8a00-81457f8f3d20": "— Моё это. Куртка, шапка, ботинки.\nДеньги? Заработал. На базаре грузил, ночами.\n(смотрит в сторону)\nЧто, нельзя?", "9281d556-d163-5537-a0e2-e4cd2e635ba5": "— Я же сказал уже. Был там. Держал его.\n(смотрит в пол)\nА дальше я не знаю. Меня там не было.", "abc6fac8-abbd-5589-b6b5-958cd368e7fe": "— Аке руку поранил? Не знаю.\nЯ его давно не видел. Учёба, работа.\n(трёт ладони о колени)"}'::jsonb where id = 'ea6167fb-4eea-5e08-ae65-e5fce24e6a6c' and not (reaction_rules @> '[{"id": "R81"}]'::jsonb);  -- Олжас Бекенов
commit;
select name, jsonb_array_length(reaction_rules) rules from characters where case_id = '029e23c3-01e0-5d19-a0e7-3e0c2446ebab' and name ~ '(Фархад|Данияр|Олжас|Валентина|Тамара)';
